create or replace function public.system_equip_title(p_title_id bigint) returns jsonb language plpgsql security definer set search_path='public','auth' as $$ declare v_user uuid:=auth.uid(); v_row public.user_titles; begin if v_user is null then raise exception 'AUTH_REQUIRED'; end if; select * into v_row from public.user_titles where user_id=v_user and title_id=p_title_id; if not found then raise exception 'TITLE_NOT_UNLOCKED'; end if; update public.user_titles set equipped=false where user_id=v_user and equipped=true; update public.user_titles set equipped=true where user_id=v_user and title_id=p_title_id returning * into v_row; insert into public.journey_events(user_id,event_type,title,detail,source,source_id,metadata) select v_user,'TITLE_EQUIPPED',t.name,t.category,'TITLE',t.id::text,jsonb_build_object('equipped',true) from public.title_catalog t where t.id=p_title_id; return jsonb_build_object('title',to_jsonb(v_row)); end $$; revoke all on function public.system_equip_title(bigint) from public,anon; grant execute on function public.system_equip_title(bigint) to authenticated,service_role;
